performance.source:
[Module load: #time];
[Alien wrap: "labs" signature: "l l" as: #publicationBench on: Integer];
[[|
[System gc]; let facts := [db retainedFactCount]; let start := [16 clockNanos];
[1 to: 20 do: [:i | [Alien wrap: "labs" signature: "l l" as: #publicationBench on: Integer]]];
[System println: [[16 clockNanos] - start]];
[System println: [[-42 publicationBench] = 42]];
[System println: [[db retainedFactCount] - facts]]
] value]
